CREATE TYPE "SupplierInvoiceStatus" AS ENUM ('RECEIVED', 'APPROVED', 'PAID', 'VOIDED');
CREATE TABLE "SupplierInvoice" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "projectId" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "purchaseOrderId" TEXT, "operationKey" VARCHAR(190) NOT NULL, "invoiceNumber" VARCHAR(96) NOT NULL, "currency" CHAR(3) NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "status" "SupplierInvoiceStatus" NOT NULL DEFAULT 'RECEIVED', "dueAt" TIMESTAMP(3), "receipt" JSONB, "revision" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupplierInvoice_pkey" PRIMARY KEY ("id"), CONSTRAINT "SupplierInvoice_org_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SupplierInvoice_project_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SupplierInvoice_supplier_fkey" FOREIGN KEY ("organizationId", "supplierId") REFERENCES "Supplier"("organizationId", "id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "SupplierInvoice_order_fkey" FOREIGN KEY ("purchaseOrderId") REFERENCES "PurchaseOrder"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "SupplierInvoice_amount_check" CHECK ("amount" > 0));
CREATE UNIQUE INDEX "SupplierInvoice_projectId_id_key" ON "SupplierInvoice"("projectId", "id");
CREATE UNIQUE INDEX "SupplierInvoice_projectId_operationKey_key" ON "SupplierInvoice"("projectId", "operationKey");
CREATE UNIQUE INDEX "SupplierInvoice_organizationId_supplierId_invoiceNumber_key" ON "SupplierInvoice"("organizationId", "supplierId", "invoiceNumber");
CREATE INDEX "SupplierInvoice_projectId_status_dueAt_idx" ON "SupplierInvoice"("projectId", "status", "dueAt");
